"""Directional pressure veto for boundary fades."""
import pandas as pd
def detect_boundary_pressure(candles,locked_range,atr,profile,config=None):
    rows=candles.tail(12).copy() if candles is not None else pd.DataFrame();width=max(float(locked_range["high"]-locked_range["low"]),1e-12);upper_near=((locked_range["high"]-rows.close)/width<=.18);lower_near=((rows.close-locked_range["low"])/width<=.18);changes=rows.close.diff();upper=min(1,float(upper_near.mean())*.45+float((changes>0).mean())*.25+min(float(profile.get("expansion_ratio") or 1)/2,1)*.2+float((rows.close>locked_range["high"]).mean())*.3);lower=min(1,float(lower_near.mean())*.45+float((changes<0).mean())*.25+min(float(profile.get("expansion_ratio") or 1)/2,1)*.2+float((rows.close<locked_range["low"]).mean())*.3);dominant="upper" if upper>lower+.1 else "lower" if lower>upper+.1 else "balanced";maximum=max(upper,lower);level="extreme" if maximum>=.8 else "high" if maximum>=float((config or {}).get("maximum_allowed_pressure",.6)) else "moderate" if maximum>=.4 else "low"
    return {"upper_pressure":upper,"lower_pressure":lower,"dominant_side":dominant,"level":level,"breakout_risk":level in {"high","extreme"},"evidence":[f"Upper pressure {upper:.2f}; lower pressure {lower:.2f}."],"warnings":[]}
